import{_ as t,c as a,o as r,ae as i}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"PROTECTING AMERICAN ENERGY FROM STATE OVERREACH","description":"","frontmatter":{"title":"PROTECTING AMERICAN ENERGY FROM STATE OVERREACH","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/protecting-american-energy-from-state-overreach/","publishDate":"2025-04-08T17:26:05-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-08-protecting-american-energy-from-state-overreach.md","filePath":"executive-orders/2025-04-08-protecting-american-energy-from-state-overreach.md"}'),n={name:"executive-orders/2025-04-08-protecting-american-energy-from-state-overreach.md"};function o(s,e,l,c,h,d){return r(),a("div",null,e[0]||(e[0]=[i('<h1 id="protecting-american-energy-from-state-overreach" tabindex="-1">PROTECTING AMERICAN ENERGY FROM STATE OVERREACH <a class="header-anchor" href="#protecting-american-energy-from-state-overreach" aria-label="Permalink to &quot;PROTECTING AMERICAN ENERGY FROM STATE OVERREACH&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/protecting-american-energy-from-state-overreach/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/protecting-american-energy-from-state-overreach/</a></p><p>Published: 2025-04-08T17:26:05-04:00</p><ul><li>The executive order emphasizes the commitment to enhancing American energy by removing obstacles to domestic energy resources, including oil, natural gas, coal, hydro, geothermal, biofuels, critical minerals, and nuclear energy.</li><li>It states that a reliable domestic energy supply is crucial for national security and economic stability.</li><li>Concerns are raised about state and local regulations that overreach or discriminate against out-of-state energy producers, which undermine the equality of states and threaten energy dominance.</li><li>Specific examples include: <ul><li>New York and Vermont imposing fines on energy producers for past greenhouse gas emissions.</li><li>California&#39;s strict carbon usage limits that create financial burdens for businesses.</li><li>Delays in state permit applications hindering energy production.</li><li>Lawsuits against energy companies for alleged climate change-related damages.</li></ul></li><li>The order asserts that such state policies elevate energy costs for all Americans and interfere with federal law and the national interest.</li><li>Measures directed: <ul><li>The Attorney General, in consultation with relevant agencies, will identify state and local laws that are unconstitutional or preempted by federal law concerning energy production and climate change initiatives.</li><li>The Attorney General is tasked with taking action to halt the enforcement of identified illegal state laws.</li><li>A report on actions taken is to be submitted to the President within 60 days, along with recommendations for further action.</li></ul></li><li>The order clarifies that it does not limit the authority of federal agencies or create any enforceable rights.</li></ul>',4)]))}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
